// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
const statusElement = document.getElementById("status");

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let movesThisTurn = 0; // Counts moves for the current player (max 2)
let statusMessage = "Player A Turn";
let gameOver = false;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  if (gameOver) {
    return false;
  }
  // Convert cellIndex (0-24) to board coordinates
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Prevent move if cell is already filled
  if (board[row][col] !== "") {
    statusMessage = "Cell already taken! " + `Player ${currentPlayer} turn`;
    return false;
  }

  // Place symbol
  board[row][col] = currentPlayer;
  movesThisTurn += 1;

  // Check for win after this move
  if (checkWin(currentPlayer)) {
    statusMessage = `Player ${currentPlayer} Wins!`;
    gameOver = true;
    return true;
  }

  // Check for tie (all cells filled)
  if (isBoardFull()) {
    statusMessage = "Tie game!";
    gameOver = true;
    return true;
  }

  // After two moves, switch player
  if (movesThisTurn === 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    movesThisTurn = 0;
  }
  statusMessage = `Player ${currentPlayer} Turn`;
  return true;
}

function renderBoard() {
  // Update the board UI
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
    // Optionally, disable cell if game over or cell is filled
    cells[i].disabled = gameOver || board[row][col] !== "";
  }
  // Update status
  if (statusElement) {
    statusElement.textContent = "Status: " + statusMessage;
  }
}

function onMove(cellIndex) {
  const moved = playMove(cellIndex);
  renderBoard();
}

// Check for 5 in a row horizontally or vertically for the given player
function checkWin(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let win = true;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let win = true;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  return false;
}

// Check if all cells are filled
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

