code.js:
// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
// const statusElement = ...;

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let movesThisTurn = 0;
let statusMessage = "";
let gameOver = false;
let winner = null;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  if (gameOver) {
    statusMessage = winner
      ? `Game over! Winner: ${winner}`
      : "Game over! It's a tie!";
    return;
  }

  console.log("User clicked on cell:", cellIndex);

  // Convert cellIndex (0-24) to board coordinates
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Only allow placing on empty cells
  if (board[row][col] !== "") {
    statusMessage = "Cell already taken!";
    return;
  }

  // Place the current player's symbol
  board[row][col] = currentPlayer;
  movesThisTurn++;

  // Check for win after this move
  if (checkWinner(currentPlayer)) {
    gameOver = true;
    winner = currentPlayer;
    statusMessage = `Game over! Winner: ${winner}`;
    return;
  }

  // Check for tie (no empty cells left)
  if (isBoardFull()) {
    gameOver = true;
    winner = null;
    statusMessage = "Game over! It's a tie!";
    return;
  }

  // After two moves, switch player
  if (movesThisTurn >= 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    movesThisTurn = 0;
  }
  statusMessage = `Player ${currentPlayer}'s turn`;
}

function renderBoard() {
  console.log("Displaying the board");
  // Update the UI to reflect the board state
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
    // Make the cell unclickable if already filled or game is over
    if (board[row][col] !== "" || gameOver) {
      cells[i].disabled = true;
    } else {
      cells[i].disabled = false;
    }
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

// Check for five in a row horizontally or vertically for the given player
function checkWinner(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let count = 0;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === player) {
        count++;
      }
    }
    if (count === 5) return true;
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let count = 0;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] === player) {
        count++;
      }
    }
    if (count === 5) return true;
  }
  // No diagonal check
  return false;
}

// Check if the board is full (tie)
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

