function checkWin(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let count = 0;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === player) {
        count++;
      }
    }
    if (count === 5) {
      return true;
    }
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let count = 0;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] === player) {
        count++;
      }
    }
    if (count === 5) {
      return true;
    }
  }
  return false;
}

// Check if the board is full (tie)
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

