const statusElement = document.getElementById("status");

// global variables
let board = Array(25).fill(""); // 改成一维更简单
let currentPlayer = "A";
let gameOver = false;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  if (board[cellIndex] !== "" || gameOver) return;

  board[cellIndex] = currentPlayer;
}

function renderBoard() {
  cells.forEach((cell, i) => {
    cell.innerText = board[i];
  });
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();

  if (checkWinner()) {
    statusElement.innerText = `Status: Player ${currentPlayer} Wins!`;
    gameOver = true;
    return;
  }

  if (!board.includes("")) {
    statusElement.innerText = "Status: Tie Game!";
    gameOver = true;
    return;
  }

  // 切换玩家
  currentPlayer = currentPlayer === "A" ? "B" : "A";
  statusElement.innerText = `Status: Player ${currentPlayer} Turn`;
}

// 检查胜利（只需要横 + 竖）
function checkWinner() {
  // 横向
  for (let r = 0; r < 5; r++) {
    let start = r * 5;
    let row = board.slice(start, start + 5);
    if (row.every(c => c === currentPlayer)) return true;
  }

  // 纵向
  for (let c = 0; c < 5; c++) {
    let col = [];
    for (let r = 0; r < 5; r++) {
      col.push(board[r * 5 + c]);
    }
    if (col.every(c => c === currentPlayer)) return true;
  }

  return false;
}

