  if (gameOver) {
    statusMessage = "Game is over. Please refresh to play again.";
    return false;
  }

  // Convert cellIndex (0-24) to board coordinates
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Only allow placing in empty cells
  if (board[row][col] !== "") {
    statusMessage = "Cell already taken!";
    return false; // Indicate move was not successful
  }

  // Place the current player's symbol (lowercase for display)
  board[row][col] = currentPlayer === "A" ? "a" : "b";
  turnSymbolCount++;

  // Check for win after this move
  if (checkWin(row, col)) {
    statusMessage = `Player ${currentPlayer} wins!`;
    gameOver = true;
    return true;
  }

  // Check for tie (no empty cells left)
  if (isBoardFull()) {
    statusMessage = "Tie game!";
    gameOver = true;
    return true;
  }

  // After two symbols, switch player
  if (turnSymbolCount >= 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    turnSymbolCount = 0;
  }

  statusMessage = `Player ${currentPlayer}'s turn`;
  return true; // Indicate move was successful
}

