  const symbol = board[row][col];
  // Horizontal check
  let count = 0;
  for (let c = 0; c < 5; c++) {
    if (board[row][c] === symbol) {
      count++;
      if (count === 5) return true;
    } else {
      count = 0;
    }
  }
  // Vertical check
  count = 0;
  for (let r = 0; r < 5; r++) {
    if (board[r][col] === symbol) {
      count++;
      if (count === 5) return true;
    } else {
      count = 0;
    }
  }
  return false;
}

