const cells = Array.from(document.querySelectorAll(".cell"));
const statusElement = document.getElementById("status");

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let moveCount = 0; // total moves played
let currentPlayer = "A"; // "A" or "B"
let turnMoves = 0; // 0 or 1, tracks if it's first/second move of the turn
let gameOver = false;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

function getRowCol(cellIndex) {
  return [Math.floor(cellIndex / 5), cellIndex % 5];
}

function playMove(cellIndex) {
  if (gameOver) return false;
  const [row, col] = getRowCol(cellIndex);
  if (board[row][col] !== "") return false;

  board[row][col] = currentPlayer;
  moveCount++;
  return true;
}

function checkWinner() {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let first = board[row][0];
    if (first && board[row].every(cell => cell === first)) {
      return first;
    }
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let first = board[0][col];
    if (first && board.every(row => row[col] === first)) {
      return first;
    }
  }
  return null;
}

function isBoardFull() {
  return moveCount >= 25;
}

function renderBoard() {
  for (let i = 0; i < 25; i++) {
    const [row, col] = getRowCol(i);
    cells[i].textContent = board[row][col];
    cells[i].disabled = !!board[row][col] || gameOver;
  }
}

function updateStatus() {
  if (gameOver) {
    const winner = checkWinner();
    if (winner) {
      statusElement.textContent = `Status: Player ${winner} Wins!`;
    } else {
      statusElement.textContent = "Status: Tie Game";
    }
  } else {
    statusElement.textContent = `Status: Player ${currentPlayer} Turn`;
  }
}

function resetGame() {
  board = [
    ["", "", "", "", ""],
    ["", "", "", "", ""],
    ["", "", "", "", ""],
    ["", "", "", "", ""],
    ["", "", "", "", ""],
  ];
  moveCount = 0;
  currentPlayer = "A";
  turnMoves = 0;
  gameOver = false;
  renderBoard();
  updateStatus();
}

