code.js:
// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
// const statusElement = ...;

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let statusMessage = "Status: Player A Turn";
let playerMoveCount = 0; // Counts moves for current player (max 2 before switching)

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);

  // Convert cellIndex (0-24) to row,col
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Ignore if cell is already filled
  if (board[row][col] !== "") {
    // statusMessage = `Status: Cell already filled. Player ${currentPlayer} Turn`;
    return;
  }

  // Place symbol for current player
  board[row][col] = currentPlayer;

  // Increment move count for this player
  playerMoveCount += 1;

  // Update the cell visually
  cells[cellIndex].textContent = currentPlayer;

  // After two moves, switch player
  if (playerMoveCount === 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    playerMoveCount = 0;
  }

  statusMessage = `Status: Player ${currentPlayer} Turn`;
}

function renderBoard() {
  console.log("Displaying the board");
  // Update the status element
  const statusElement = document.getElementById("status");
  if (statusElement) {
    statusElement.textContent = statusMessage;
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

