    currentPlayer = currentPlayer === "A" ? "B" : "A";
    playerMoveCount = 0;
  }

  statusMessage = `Status: Player ${currentPlayer} Turn`;
}

function renderBoard() {
  console.log("Displaying the board");
  // Update the status element
  const statusElement = document.getElementById("status");
  if (statusElement) {
    statusElement.textContent = statusMessage;
  }
}

// Check if the current player has 5 in a row horizontally or vertically
function checkWin(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let win = true;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let win = true;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  return false;
}

// Check if the board is full (tie)
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

// Check if the game is over (win or tie)
function gameOver() {
  return checkWin("A") || checkWin("B") || isBoardFull();
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

