// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
// const statusElement = ...;

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
// Turn system: A->A->B->B->A->A...
let currentPlayer = "A";
let movesThisTurn = 0; // 0 or 1, after 2 moves switch player
let statusMessage = "";

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);

  // Convert cellIndex (0-24) to row,col
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Only allow placing in empty cells
  if (board[row][col] !== "") {
    statusMessage = "Cell already taken!";
    return;
  }

  // Place current player's symbol
  board[row][col] = currentPlayer;

  // Check for win after placing
  const winner = checkWinner();
  if (winner) {
    statusMessage = `Player ${winner} wins!`;
    // Optionally: disable further moves by removing event listeners or setting a flag
    // For now, just return and don't update turn
    return;
  }

  movesThisTurn += 1;

  if (movesThisTurn >= 2) {
    // Switch player after 2 moves
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    movesThisTurn = 0;
  }

  statusMessage = `Player ${currentPlayer}'s turn (${movesThisTurn + 1}/2)`;
}

function renderBoard() {
  // Update the board UI
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
  }

  // Show status message
  let statusDiv = document.getElementById("status-message");
  if (!statusDiv) {
    statusDiv = document.createElement("div");
    statusDiv.id = "status-message";
    statusDiv.style.marginTop = "10px";
    document.querySelector("main.container").appendChild(statusDiv);
  }
  statusDiv.textContent = statusMessage;
}

function checkWinner() {
  // Check rows
  for (let row = 0; row < 5; row++) {
    if (
      board[row][0] !== "" &&
      board[row][0] === board[row][1] &&
      board[row][1] === board[row][2] &&
      board[row][2] === board[row][3] &&
      board[row][3] === board[row][4]
    ) {
      return board[row][0];
    }
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    if (
      board[0][col] !== "" &&
      board[0][col] === board[1][col] &&
      board[1][col] === board[2][col] &&
      board[2][col] === board[3][col] &&
      board[3][col] === board[4][col]
    ) {
      return board[0][col];
    }
  }
  // Check main diagonal
  if (
    board[0][0] !== "" &&
    board[0][0] === board[1][1] &&
    board[1][1] === board[2][2] &&
    board[2][2] === board[3][3] &&
    board[3][3] === board[4][4]
  ) {
    return board[0][0];
  }
  // Check anti-diagonal
  if (
    board[0][4] !== "" &&
    board[0][4] === board[1][3] &&
    board[1][3] === board[2][2] &&
    board[2][2] === board[3][1] &&
    board[3][1] === board[4][0]
  ) {
    return board[0][4];
  }
  return null;
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

