code.js:
// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
// const statusElement = ...;

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A"; // Start with player A
let turnSymbolCount = 0; // Counts how many symbols placed in current turn (max 2)
let statusMessage = "";
let gameOver = false;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);

  if (gameOver) {
    statusMessage = "Game is over. No more moves allowed.";
    return false;
  }

  // Convert cellIndex (0-24) to board coordinates
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Ignore if cell is already filled
  if (board[row][col] !== "") {
    statusMessage = "Cell already filled!";
    return false; // indicate move was not successful
  }

  // Place current player's symbol
  board[row][col] = currentPlayer;
  turnSymbolCount += 1;

  // Check for win or tie after move
  if (checkWin(currentPlayer)) {
    statusMessage = `Player ${currentPlayer} wins!`;
    gameOver = true;
    return true;
  } else if (isBoardFull()) {
    statusMessage = "It's a tie!";
    gameOver = true;
    return true;
  }

  // After 2 moves, switch player
  if (turnSymbolCount === 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    turnSymbolCount = 0;
  }

  statusMessage = `Player ${currentPlayer}'s turn.`;
  return true; // indicate move was successful
}

function renderBoard() {
  console.log("Displaying the board");
  // Update the UI to reflect the board state
  cells.forEach((cell, idx) => {
    const row = Math.floor(idx / 5);
    const col = idx % 5;
    cell.textContent = board[row][col];
    cell.disabled = board[row][col] !== "" || gameOver;
  });

  // Optionally display status somewhere
  // For now, log to console
  console.log(statusMessage);
}

function onMove(cellIndex) {
  const moveMade = playMove(cellIndex);
  renderBoard();
}

// Check for 5 in a row horizontally or vertically for the given player
function checkWin(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let count = 0;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === player) {
        count++;
      }
    }
    if (count === 5) {
      return true;
    }
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let count = 0;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] === player) {
        count++;
      }
    }
    if (count === 5) {
      return true;
    }
  }
  // No diagonal win allowed
  return false;
}

// Check if the board is full (tie)
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

