  // Check rows
  for (let row = 0; row < 5; row++) {
    let count = 0;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === player) {
        count++;
      } else {
        break;
      }
    }
    if (count === 5) {
      return true;
    }
  }

  // Check columns
  for (let col = 0; col < 5; col++) {
    let count = 0;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] === player) {
        count++;
      } else {
        break;
      }
    }
    if (count === 5) {
      return true;
    }
  }

  // No win found
  return false;
}

/**
 * Returns true if the board is full (no empty cells)
 */
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
