// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
// const statusElement = ...;

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];

// Hidden turn tracker for AABBAABB... pattern
let turnCounter = 0;
function getCurrentPlayer() {
  // Each player gets two turns in a row: 0,1 -> A; 2,3 -> B; 4,5 -> A; 6,7 -> B; etc.
  const mod = turnCounter % 4;
  return (mod === 0 || mod === 1) ? "A" : "B";
}

let currentPlayer = "";
let statusMessage = "";
let gameOver = false;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// Check for 5 in a row horizontally or vertically for a given symbol
function checkFiveInARow(symbol) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let count = 0;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === symbol) {
        count++;
      } else {
        count = 0;
      }
      if (count === 5) {
        return true;
      }
    }
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let count = 0;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] === symbol) {
        count++;
      } else {
        count = 0;
      }
      if (count === 5) {
        return true;
      }
    }
  }
  return false;
}

// Check if the board is full
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

// JS functions
function playMove(cellIndex) {
  if (gameOver) return;

  console.log("User clicked on cell:", cellIndex);

  // Convert cellIndex (0-24) to board coordinates
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // If the cell is already filled, do nothing
  if (board[row][col] !== "") {
    return;
  }

  // Hidden turn tracker logic
  currentPlayer = getCurrentPlayer();

  // Mark the board with the current player
  board[row][col] = currentPlayer;

  // Check for win condition
  if (checkFiveInARow(currentPlayer)) {
    gameOver = true;
    statusMessage = `Player ${currentPlayer} wins!`;
  } else if (isBoardFull()) {
    gameOver = true;
    statusMessage = "Board is full. No winner!";
  }

  // Advance the turn counter for next move
  turnCounter++;
}

function renderBoard() {
  console.log("Displaying the board");
  // Update the UI to show A or B in each cell
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
    // Disable the cell if it has been played or game is over
    if (board[row][col] !== "" || gameOver) {
      cells[i].disabled = true;
    } else {
      cells[i].disabled = false;
    }
  }
  // Optionally display status message (could add a status element in HTML)
  if (statusMessage) {
    console.log(statusMessage);
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

