    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") return false;
    }
  }
  return true;
}

// Simple win check: 5 in a row horizontally, vertically, or diagonally
function checkWin(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let win = true;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let win = true;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  // Check main diagonal
  let win = true;
  for (let i = 0; i < 5; i++) {
    if (board[i][i] !== player) {
      win = false;
      break;
    }
  }
  if (win) return true;
  // Check anti-diagonal
  win = true;
  for (let i = 0; i < 5; i++) {
    if (board[i][4 - i] !== player) {
      win = false;
      break;
    }
  }
  if (win) return true;

