  min-height: 100vh;
  min-width: 100vw;
  display: flex;
  align-items: center;
  justify-content: center;
}

.status {
  margin-top: 0;
  font-size: 1.2em;
  min-height: 1.5em;
}

.header-block {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  margin-bottom: 10px;
  width: 100%;
  max-width: 320px;
  /* 5 cells * 60px + 4 gaps * 4px = 320px */
  box-sizing: border-box;
}

.container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100vw;
  height: 100vh;
}

.board {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 4px;
}

.cell {
  min-width: 60px;
  min-height: 60px;
}

code.js:
// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
// Status element
const statusElement = document.getElementById("status");

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "";
let statusMessage = "";

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);
}

function renderBoard() {
  console.log("Displaying the board");
  // Update status message
  if (statusElement) {
    statusElement.textContent = `Status: ${statusMessage}`;
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

// Example: update statusMessage and render on load
window.addEventListener("DOMContentLoaded", () => {
  statusMessage = currentPlayer
    ? `Turn: ${currentPlayer}`
    : "Game has not started";
  renderBoard();
});

