code.js:
// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
// Status element
const statusElement = document.getElementById("status");

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let players = ["A", "B"];
let currentPlayer = "A";
let currentTurn = 0; // 0 or 1, each player gets two turns
let statusMessage = "";
let gameOver = false;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  if (gameOver) return;

  console.log("User clicked on cell:", cellIndex);

  // Convert cellIndex (0..24) to row,col
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Ignore if cell is already filled
  if (board[row][col] !== "") return;

  // Place current player's mark
  board[row][col] = currentPlayer;

  // Check for win
  if (checkWin(currentPlayer)) {
    statusMessage = `Player ${currentPlayer} wins!`;
    gameOver = true;
    return;
  }

  // Check for draw
  if (isBoardFull()) {
    statusMessage = "Draw!";
    gameOver = true;
    return;
  }

  // Each player gets two turns in a row
  currentTurn += 1;
  if (currentTurn === 2) {
    // Switch player and reset turn counter
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    currentTurn = 0;
  }
  statusMessage = `Player ${currentPlayer}'s Turn`;
}

function renderBoard() {
  console.log("Displaying the board");
  // Update status message
  if (statusElement) {
    statusElement.textContent = `Status: ${statusMessage}`;
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") return false;
    }
  }
  return true;
}

// Simple win check: 5 in a row horizontally, vertically, or diagonally
function checkWin(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let win = true;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  // Check columns
