body {
  margin: 10px;
  min-height: 100vh;
  min-width: 100vw;
  display: flex;
  align-items: center;
  justify-content: center;
}

.status {
  margin-top: 0;
  font-size: 1.2em;
  min-height: 1.5em;
}

.header-block {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  margin-bottom: 10px;
  width: 100%;
  max-width: 320px;
  /* 5 cells * 60px + 4 gaps * 4px = 320px */
  box-sizing: border-box;
}

.container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100vw;
  height: 100vh;
}

.board {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 4px;
}

.cell {
  min-width: 60px;
  min-height: 60px;
}

