- Player A and Player B alternate turns, starting with A.
- Each player places exactly 2 symbols per turn.
- After 2 symbols, it switches to the other player.
*/

let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A"; // Start with player A
let symbolsPlacedThisTurn = 0; // Counts symbols placed in current turn
let statusMessage = "";
let gameOver = false;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);

  if (gameOver) {
    return;
  }

  // Convert cellIndex (0-24) to row,col
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Only allow placing if cell is empty
  if (board[row][col] !== "") {
    return;
  }

  // Place current player's symbol
  board[row][col] = currentPlayer;
  symbolsPlacedThisTurn += 1;

  // Check for win after this move
  if (checkWin(currentPlayer)) {
    statusMessage = `Player ${currentPlayer} wins!`;
    gameOver = true;
    return;
  }

  // Check for tie (no empty cells)
  if (isBoardFull()) {
    statusMessage = "It's a tie!";
    gameOver = true;
    return;
  }

  // After 2 placements, switch player
  if (symbolsPlacedThisTurn >= 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    symbolsPlacedThisTurn = 0;
  }
}

function renderBoard() {
  console.log("Displaying the board");
  // Update the UI to reflect the board state
  cells.forEach((cell, idx) => {
    const row = Math.floor(idx / 5);
    const col = idx % 5;
    cell.textContent = board[row][col];
  });

  // Optionally display status message (e.g., in the console)
  if (statusMessage) {
    console.log(statusMessage);
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

// Check for 5 in a row horizontally or vertically for the given player
function checkWin(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let count = 0;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === player) {
        count++;
      }
    }
    if (count === 5) {
      return true;
    }
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let count = 0;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] === player) {
        count++;
      }
    }
    if (count === 5) {
      return true;
    }
  }
  return false;
}

// Check if the board is full (tie)
function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

