// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
const statusElement = document.getElementById("status");

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let movesThisTurn = 0;
let gameOver = false;
let winner = null;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions

function playMove(cellIndex) {
  if (gameOver) return false;

  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Only allow placing if cell is empty
  if (board[row][col] !== "") {
    return false;
  }

  board[row][col] = currentPlayer;
  movesThisTurn += 1;

  // Check for win after this move
  if (checkWin(row, col, currentPlayer)) {
    gameOver = true;
    winner = currentPlayer;
  } else if (isBoardFull()) {
    gameOver = true;
    winner = null;
  } else if (movesThisTurn === 2) {
    // Switch player after 2 moves
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    movesThisTurn = 0;
  }

  return true;
}

function renderBoard() {
  // Update the board UI
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
    cells[i].disabled = !!board[row][col] || gameOver;
  }

  // Update status
  if (gameOver) {
    if (winner === "A") {
      statusElement.textContent = "Status: Player A wins!";
    } else if (winner === "B") {
      statusElement.textContent = "Status: Player B wins!";
    } else {
      statusElement.textContent = "Status: Tie game!";
    }
  } else {
    statusElement.textContent = `Status: Player ${currentPlayer} Turn`;
  }
}

function onMove(cellIndex) {
  const moved = playMove(cellIndex);
  renderBoard();
}

// Check for 5 in a row horizontally or vertically
function checkWin(row, col, player) {
  // Check row
  let rowCount = 0;
  for (let c = 0; c < 5; c++) {
    if (board[row][c] === player) {
      rowCount++;
      if (rowCount === 5) return true;
    } else {
      rowCount = 0;
    }
  }

  // Check column
  let colCount = 0;
  for (let r = 0; r < 5; r++) {
    if (board[r][col] === player) {
      colCount++;
      if (colCount === 5) return true;
    } else {
      colCount = 0;
    }
  }

  return false;
}

function isBoardFull() {
  for (let r = 0; r < 5; r++) {
    for (let c = 0; c < 5; c++) {
      if (board[r][c] === "") return false;
    }
  }
  return true;
}

// Initial render
renderBoard();

