// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));

const statusElement = document.getElementById("status-message");

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let counter = 0;
let statusMessage = "Status: Player A Turn";

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// Render the initial board and status message on page load
renderBoard();

/**
 * Check if a whole row in the board is filled with the same non-empty letter.
 * Returns the letter ("A" or "B") if a row is filled, otherwise returns null.
 */
function checkFullRow(board) {
  for (let row = 0; row < 5; row++) {
    const first = board[row][0];
    if (first !== "" && board[row].every(cell => cell === first)) {
      return first;
    }
  }
  return null;
}

/**
 * Check if all elements in the board are not "" (i.e., the board is full).
 * Returns true if the board is full, false otherwise.
 */
function isBoardFull(board) {
  return board.every(row => row.every(cell => cell !== ""));
}

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);
  idx1 = Math.floor(cellIndex / 5);
  idx2 = cellIndex - (5 * idx1);

  if (board[idx1][idx2] == "") {
    board[idx1][idx2] = currentPlayer;
    counter = counter + 1;
    if (currentPlayer === "A" & counter == 2) {
      currentPlayer = "B";
      statusMessage = "Status: Player B Turn";
      counter = 0;
    } else if (currentPlayer === "B" & counter == 2){
      currentPlayer = "A";
      statusMessage = "Status: Player A Turn";
      counter = 0;
    }
    console.log("currentPlayer", currentPlayer)
    console.log("Idx:", idx1, idx2);

    if (checkFullRow(board) === "A") {
      statusMessage = "Status: Player A Wins!";
    } else if (checkFullRow(board) === "B") {
      statusMessage = "Status: Player B Wins!";
    } else if 

  }


}

function renderBoard() {
  // Update each cell's text to match the board state
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      const cellIndex = row * 5 + col;
      cells[cellIndex].textContent = board[row][col];
    }
  }
  // Update the status message in the h2 tag
  if (statusElement) {
    statusElement.textContent = statusMessage;
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

