// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
// const statusElement = ...;

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];
let currentPlayer = "A";
let counter = 0;
let statusMessage = "";

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);
  idx1 = Math.floor(cellIndex / 5);
  idx2 = cellIndex - (5 * idx1);

  if (board[idx1][idx2] == "") {
    board[idx1][idx2] = currentPlayer;
    counter = counter + 1;
    if (currentPlayer === "A" & counter == 2) {
      currentPlayer = "B";
      counter = 0;
    } else if (currentPlayer === "B" & counter == 2){
      currentPlayer = "A";
      counter = 0;
    }
    console.log("currentPlayer", currentPlayer)
    console.log("Idx:", idx1, idx2);
  }

}

function renderBoard() {
  // Update each cell's text to match the board state
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      const cellIndex = row * 5 + col;
      cells[cellIndex].textContent = board[row][col];
    }
  }
}

function onMove(cellIndex) {
  playMove(cellIndex);
  renderBoard();
}

