// HTML elements
const cells = Array.from(document.querySelectorAll(".cell"));
// const statusElement = ...;

// global variables
let board = [
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
  ["", "", "", "", ""],
];

let currentPlayer = "A"; // Start with A
let movesThisTurn = 0;   // Counts moves in current player's turn (max 2)
let statusMessage = "";
let gameOver = false;

// connect the HTML + JS
cells.forEach((cell) => {
  cell.addEventListener("click", (event) => {
    const index = Number(event.currentTarget.dataset.index);
    onMove(index);
  });
});

function checkWin(player) {
  // Check rows
  for (let row = 0; row < 5; row++) {
    let win = true;
    for (let col = 0; col < 5; col++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  // Check columns
  for (let col = 0; col < 5; col++) {
    let win = true;
    for (let row = 0; row < 5; row++) {
      if (board[row][col] !== player) {
        win = false;
        break;
      }
    }
    if (win) return true;
  }
  return false;
}

function isBoardFull() {
  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      if (board[row][col] === "") {
        return false;
      }
    }
  }
  return true;
}

// JS functions
function playMove(cellIndex) {
  console.log("User clicked on cell:", cellIndex);

  if (gameOver) {
    statusMessage = "Game is over!";
    return false;
  }

  // Convert cellIndex (0-24) to row,col
  const row = Math.floor(cellIndex / 5);
  const col = cellIndex % 5;

  // Ignore if cell is already filled
  if (board[row][col] !== "") {
    statusMessage = "Cell already filled!";
    return false; // Indicate move was not made
  }

  // Place current player's symbol
  board[row][col] = currentPlayer;
  movesThisTurn++;

  // Check for win after move
  if (checkWin(currentPlayer)) {
    statusMessage = `Player ${currentPlayer} wins!`;
    gameOver = true;
    return true;
  }

  // Check for tie (no empty cells left)
  if (isBoardFull()) {
    statusMessage = "It's a tie!";
    gameOver = true;
    return true;
  }

  // After two moves, switch player
  if (movesThisTurn >= 2) {
    currentPlayer = currentPlayer === "A" ? "B" : "A";
    movesThisTurn = 0;
  }

  statusMessage = `Player ${currentPlayer}'s turn.`;
  return true; // Indicate move was made
}

function renderBoard() {
  // Update the board UI
  for (let i = 0; i < 25; i++) {
    const row = Math.floor(i / 5);
    const col = i % 5;
    cells[i].textContent = board[row][col];
  }

  // Optionally, display status somewhere (console for now)
  console.log("Displaying the board");
  console.log(statusMessage);
}

function onMove(cellIndex) {
  const moveMade = playMove(cellIndex);
  renderBoard();
}

